choose.when:
SELECT ,
        AS heat_score
FROM tb_post
LEFT JOIN tb_post_count ON tb_post_count.post_id = tb_post.id
WHERE tb_post.deleted = 0
  AND 
  AND tb_post.bar_id = #{barId}

    AND tb_post.user_id = #{userId}


    AND (
         < #{lastScore}
        OR ( = #{lastScore} AND tb_post.id < #{lastId})
    )

ORDER BY heat_score DESC, tb_post.id DESC
LIMIT #{limit}

choose.otherwise:
SELECT 
FROM tb_post
WHERE deleted = 0
  AND 

    AND user_id = #{userId}


    AND id < #{lastId}

ORDER BY id DESC
LIMIT #{limit}

