mapper.select:
SELECT bar_id AS barId, COUNT(*) AS postCount FROM tb_post WHERE deleted = 0 AND bar_id IN
#{id}
GROUP BY bar_id

SELECT p.id, p.bar_id, p.user_id, p.title, p.content_preview, p.content_uuid, p.cover_image, p.image_count, p.deleted, p.event_status, p.embed_status, p.analysis_status, p.analysis_retry_count, p.analysis_time, p.create_time, p.update_time FROM tb_post p LEFT JOIN tb_post_analysis a ON a.post_id = p.id WHERE p.deleted = 0
AND p.bar_id = #{barId}
AND a.handler_action IS NULL
AND p.analysis_status = 3
ORDER BY p.id DESC LIMIT #{limit} OFFSET #{offset}
